const path = require("path");

const fontDir = path.resolve(__dirname, "../../../../src/web/static/fonts/bmfonts");
const fontFiles = [
    "Roboto72White.fnt",
    "RobotoBlack72White.fnt",
    "RobotoMono72White.fnt",
    "RobotoSlab72White.fnt"
];
const imageFiles = [
    "Roboto72White.png",
    "RobotoBlack72White.png",
    "RobotoMono72White.png",
    "RobotoSlab72White.png"
];

for (const file of [...fontFiles, ...imageFiles]) {
    jest.unstable_mockModule(path.join(fontDir, file), () => ({
        default: `mock-${file}`
    }));
}

let mockImage;
let mockTextImage;
let mockFont;
let MockJimp;
let measureText;
let measureTextHeight;
let loadFont;
let AddTextToImage;
let OperationError;

jest.unstable_mockModule("jimp", () => ({
    Jimp: MockJimp,
    JimpMime: { png: "image/png" },
    ResizeStrategy: { BICUBIC: "bicubic", BILINEAR: "bilinear" },
    measureText,
    measureTextHeight,
    loadFont
}));

const pngInput = () => new Uint8Array([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    0x00, 0x00, 0x00, 0x0d
]).buffer;

const makeArgs = (overrides = {}) => {
    const args = [
        "Hello",
        "None",
        "None",
        0,
        0,
        32,
        "Roboto",
        255,
        255,
        255,
        255
    ];
    for (const [index, value] of Object.entries(overrides)) {
        args[Number(index)] = value;
    }
    return args;
};

beforeAll(async () => {
    mockImage = {
        width: 100,
        height: 80,
        mime: "image/png",
        blit: jest.fn(),
        getBuffer: jest.fn()
    };
    mockTextImage = {
        width: 20,
        height: 10,
        print: jest.fn(),
        scale: jest.fn()
    };
    const bitmap = new Uint8Array([200, 100, 50, 250]);
    mockFont = {
        pages: [{ bitmap: { width: 1, height: 1, data: bitmap } }]
    };

    MockJimp = jest.fn(function(options) {
        mockTextImage.width = options.width;
        mockTextImage.height = options.height;
        return mockTextImage;
    });
    MockJimp.read = jest.fn();

    measureText = jest.fn(() => 20);
    measureTextHeight = jest.fn(() => 10);
    loadFont = jest.fn(async () => mockFont);

    globalThis.self = {
        docURL: "https://example.test/cyberchef",
        sendStatusMessage: jest.fn()
    };

    ({ default: AddTextToImage } = await import("../../../../src/core/operations/AddTextToImage.mjs"));
    ({ default: OperationError } = await import("../../../../src/core/errors/OperationError.mjs"));
});

beforeEach(() => {
    jest.clearAllMocks();

    mockImage.width = 100;
    mockImage.height = 80;
    mockImage.mime = "image/png";
    mockImage.blit.mockReturnValue(mockImage);
    mockImage.getBuffer.mockResolvedValue({ buffer: new Uint8Array([9, 8, 7]).buffer });

    mockTextImage.width = 20;
    mockTextImage.height = 10;
    mockTextImage.print.mockReturnValue(mockTextImage);
    mockTextImage.scale.mockImplementation(function({ f }) {
        this.width *= f;
        this.height *= f;
        return this;
    });

    mockFont.pages = [{
        bitmap: { width: 1, height: 1, data: new Uint8Array([200, 100, 50, 250]) }
    }];

    MockJimp.read.mockResolvedValue(mockImage);
    measureText.mockReturnValue(20);
    measureTextHeight.mockReturnValue(10);
    loadFont.mockResolvedValue(mockFont);
    globalThis.self.sendStatusMessage.mockClear();
});

afterAll(() => {
    delete globalThis.self;
    delete globalThis.importScripts;
});

describe("AddTextToImage.run", () => {
    test("rejects inputs that are not images before attempting to read them", async () => {
        const operation = new AddTextToImage();
        const input = new Uint8Array([1, 2, 3, 4]).buffer;

        await expect(operation.run(input, makeArgs())).rejects.toMatchObject({
            type: "OperationError",
            message: "Invalid file type."
        });
        expect(MockJimp.read).not.toHaveBeenCalled();
    });

    test("wraps image loading failures in an OperationError", async () => {
        MockJimp.read.mockRejectedValueOnce(new Error("bad image"));

        await expect(new AddTextToImage().run(pngInput(), makeArgs())).rejects.toMatchObject({
            type: "OperationError",
            message: "Error loading image. (Error: bad image)"
        });
    });

    test("renders, positions, and exports text using the default position and size", async () => {
        const operation = new AddTextToImage();
        const args = makeArgs();
        const output = await operation.run(pngInput(), args);

        expect(MockJimp.read).toHaveBeenCalledWith(pngInput());
        expect(measureText).toHaveBeenCalledWith(mockFont, "Hello");
        expect(measureTextHeight).toHaveBeenCalledWith(mockFont, "Hello");
        expect(MockJimp).toHaveBeenCalledWith({ width: 20, height: 10 });
        expect(mockTextImage.print).toHaveBeenCalledWith({
            font: mockFont,
            x: 0,
            y: 0,
            text: "Hello"
        });
        expect(mockTextImage.scale).toHaveBeenCalledWith({
            f: 32 / 72,
            mode: "bicubic"
        });
        expect(mockImage.blit).toHaveBeenCalledWith({
            src: mockTextImage,
            x: 0,
            y: 0
        });
        expect(mockImage.getBuffer).toHaveBeenCalledWith("image/png");
        expect(output).toBe(mockImage.getBuffer.mock.results[0].value.buffer);
    });

    test("loads the requested font and changes every font bitmap channel", async () => {
        await new AddTextToImage().run(
            pngInput(),
            makeArgs({ 6: "Roboto Mono", 7: 128, 8: 64, 9: 0, 10: 255 })
        );

        expect(loadFont).toHaveBeenCalledWith(
            "https://example.test/cyberchef/mock-RobotoMono72White.fnt"
        );
        expect(Array.from(mockFont.pages[0].bitmap.data)).toEqual([73, 0, 0, 250]);
    });

    test.each([
        ["Roboto", "Roboto72White.fnt"],
        ["Roboto Black", "RobotoBlack72White.fnt"],
        ["Roboto Mono", "RobotoMono72White.fnt"],
        ["Roboto Slab", "RobotoSlab72White.fnt"]
    ])("selects the %s font face", async (fontFace, fileName) => {
        await new AddTextToImage().run(pngInput(), makeArgs({ 6: fontFace }));

        expect(loadFont).toHaveBeenCalledWith(
            `https://example.test/cyberchef/mock-${fileName}`
        );
    });

    test.each([
        ["Left", "Top", 0, 0],
        ["Center", "Middle", 45, 37.5],
        ["Right", "Bottom", 80, 70]
    ])("applies %s/%s alignment after scaling the text image", async (hAlign, vAlign, x, y) => {
        await new AddTextToImage().run(
            pngInput(),
            makeArgs({ 1: hAlign, 2: vAlign, 3: 7, 4: 9 })
        );

        expect(mockImage.blit).toHaveBeenCalledWith({
            src: mockTextImage,
            x,
            y
        });
    });

    test("keeps manually supplied coordinates when alignment is None", async () => {
        await new AddTextToImage().run(
            pngInput(),
            makeArgs({ 1: "None", 2: "None", 3: 12, 4: 34 })
        );

        expect(mockImage.blit).toHaveBeenCalledWith({
            src: mockTextImage,
            x: 12,
            y: 34
        });
    });

    test("uses bilinear scaling for sizes below one and skips scaling at size one", async () => {
        await new AddTextToImage().run(pngInput(), makeArgs({ 5: 0.5 }));
        expect(mockTextImage.scale).toHaveBeenLastCalledWith({
            f: 0.5 / 72,
            mode: "bilinear"
        });

        jest.clearAllMocks();
        mockImage.getBuffer.mockResolvedValue({ buffer: new ArrayBuffer(1) });
        await new AddTextToImage().run(pngInput(), makeArgs({ 5: 1 }));
        expect(mockTextImage.scale).not.toHaveBeenCalled();
    });

    test("exports GIF input as PNG", async () => {
        mockImage.mime = "image/gif";

        await new AddTextToImage().run(pngInput(), makeArgs());

        expect(mockImage.getBuffer).toHaveBeenCalledWith("image/png");
    });

    test("wraps font loading failures in an OperationError", async () => {
        loadFont.mockRejectedValueOnce(new Error("no font"));

        await expect(new AddTextToImage().run(pngInput(), makeArgs())).rejects.toMatchObject({
            type: "OperationError",
            message: "Error loading font. (Error: no font)"
        });
    });

    test("wraps text rendering failures in an OperationError", async () => {
        mockTextImage.print.mockImplementationOnce(() => {
            throw new Error("cannot print");
        });

        await expect(new AddTextToImage().run(pngInput(), makeArgs())).rejects.toMatchObject({
            type: "OperationError",
            message: "Error adding text to image. (Error: cannot print)"
        });
    });

    test("wraps export failures in an OperationError", async () => {
        mockImage.getBuffer.mockRejectedValueOnce(new Error("cannot encode"));

        await expect(new AddTextToImage().run(pngInput(), makeArgs())).rejects.toMatchObject({
            type: "OperationError",
            message: "Error exporting image. (Error: cannot encode)"
        });
    });

    test("sends a worker status message when running in a worker environment", async () => {
        globalThis.importScripts = jest.fn();

        await new AddTextToImage().run(pngInput(), makeArgs());

        expect(globalThis.self.sendStatusMessage).toHaveBeenCalledWith("Adding text to image...");
    });
});
