function makeArgs(overrides = {}) {
    const args = DEFAULT_ARGS.slice();
    for (const key of Object.keys(overrides)) {
        if (!Object.prototype.hasOwnProperty.call(ARG_INDEX, key)) {
            throw new Error(`Unknown argument override: ${key}`);
        }
        args[ARG_INDEX[key]] = overrides[key];
    }
    return args;
}

/**
