 *
 * @param {string} character - "x" or "."
 * @returns {Object}
 */
function customLugs(character) {
    const overrides = {pattern: "Custom"};
    for (const wheel of CUSTOM_WHEELS) {
        overrides[wheel.key] = character.repeat(wheel.length);
    }
    return overrides;
}

/**
 * Return the error thrown by fn, failing if it does not throw.
 *
 * @param {Function} fn
 * @returns {Error}
 */
function captureError(fn) {
    try {
        fn();
    } catch (error) {
        return error;
    }
    throw new Error("Expected the operation to throw, but it did not");
}

/**
