{"command": "cd /testbed && cat > test/core/operations/ParseIPv6Address/run.test.js <<'EOF'
let ParseIPv6Address;
let OperationError;

beforeAll(async () => {
    ParseIPv6Address = (await import("../../../../src/core/operations/ParseIPv6Address.mjs")).default;
    OperationError = (await import("../../../../src/core/errors/OperationError.mjs")).default;
});

/**
 * Runs the operation with a fresh instance.
 *
 * @param {string} input
 * @param {Object[]} [args]
 * @returns {string}
 */
function run(input, args = []) {
    return new ParseIPv6Address().run(input, args);
}

describe("ParseIPv6Address.run - basic formatting", () => {
    test("prints longhand and shorthand forms of an ordinary global address", () => {
        expect(run("2001:1:2:3:4:5:6:7")).toBe(
            "Longhand:  2001:0001:0002:0003:0004:0005:0006:0007\n" +
            "Shorthand: 2001:1:2:3:4:5:6:7\n"
        );
    });

    test("normalises uppercase input to lowercase hexadecimal", () => {
        const out = run("2001:DB8::1");
        expect(out).toContain("Longhand:  2001:0db8:0000:0000:0000:0000:0000:0001");
        expect(out).toContain("Shorthand: 2001:db8::1");
    });

    test("accepts and trims surrounding whitespace", () => {
        expect(run("  2001:db8::1  ")).toBe(run("2001:db8::1"));
    });

    test("ignores the args parameter", () => {
        const input = "2001:db8::1";
        expect(run(input, [{ unused: true }, 42])).toBe(run(input));
    });
});

describe("ParseIPv6Address.run - special and reserved addresses", () => {
    test("identifies the unspecified address", () => {
        const out = run("::");
        expect(out).toContain("Longhand:  0000:0000:0000:0000:0000:0000:0000:0000");
        expect(out).toContain("Shorthand: ::");
        expect(out).toContain("Unspecified address corresponding to 0.0.0.0/32 in IPv4.");
        expect(out).toContain("Unspecified address range: ::/128");
        expect(out).not.toContain("Loopback");
    });

    test("identifies the loopback address", () => {
        const out = run("::1");
        expect(out).toContain("Longhand:  0000:0000:0000:0000:0000:0000:0000:0001");
        expect(out).toContain("Shorthand: ::1");
        expect(out).toContain("Loopback address to the local host corresponding to 127.0.0.1/8 in IPv4.");
        expect(out).toContain("Loopback addresses range: ::1/128");
