 */

import ParseUNIXFilePermissions from "../../../../src/core/operations/ParseUNIXFilePermissions.mjs";
import OperationError from "../../../../src/core/errors/OperationError.mjs";

const op = new ParseUNIXFilePermissions();

/**
 * Runs the operation with the given input.
 *
 * @param {string} input
 * @returns {string}
 */
function run(input) {
    return op.run(input, []);
}

const BORDER = " +---------+-------+-------+-------+";
const HEADER = " |         | User  | Group | Other |";

/**
 * Builds a single permission matrix row exactly as the operation renders it.
 *
 * @param {string} label
 * @param {boolean[]} flags - [user, group, other]
 * @returns {string}
 */
function matrixRow(label, flags) {
    return ` |${label.padStart(8)} |` +
        flags.map(f => (f ? "   X   " : "       ")).join("|") + "|";
}

/**
 * Builds the full permission matrix block which terminates every output.
 *
 * @param {{user: boolean[], group: boolean[], other: boolean[]}} perms
 * @returns {string}
 */
function matrix(perms) {
    return [
        BORDER,
        HEADER,
        BORDER,
        matrixRow("Read", [perms.user[0], perms.group[0], perms.other[0]]),
        BORDER,
        matrixRow("Write", [perms.user[1], perms.group[1], perms.other[1]]),
        BORDER,
        matrixRow("Execute", [perms.user[2], perms.group[2], perms.other[2]]),
        BORDER
    ].join("\n");
}

/**
 * Asserts that the output contains the expected textual, octal and (optional)
 * file type lines, in that order, and returns the output lines for further
 * assertions.
 *
 * @param {string} output
 * @param {string} textual
 * @param {string} octal
 * @param {string|null} fileType
 */
function expectSummary(output, textual, octal, fileType = null) {
    expect(output).toContain(`Textual representation: ${textual}`);
    expect(output).toContain(`Octal representation:   ${octal}`);

    const lines = output.split("\n");
    expect(lines[0]).toBe(`Textual representation: ${textual}`);
    expect(lines[1]).toBe(`Octal representation:   ${octal}`);

    if (fileType === null) {
        expect(output).not.toContain("File type:");
    } else {
        expect(lines[2]).toBe(`File type: ${fileType}`);
    }
}

/**
 * Returns the flag lines ("The setuid flag is set", ...) found in the output.
 *
 * @param {string} output
 * @returns {string[]}
 */
function flagLines(output) {
    return output.split("\n").filter(l => l.startsWith("The "));
}


describe("ParseUNIXFilePermissions.run: octal input", () => {

    test("parses a three digit octal permission string", () => {
        const output = run("755");

        expectSummary(output, "-rwxr-xr-x", "0755");
        expect(output).toBe(
            "Textual representation: -rwxr-xr-x\n" +
            "Octal representation:   0755\n" +
            "\n" +
            matrix({
                user:  [true, true, true],
                group: [true, false, true],
                other: [true, false, true]
            })
        );
    });

    test("does not report a file type for octal input", () => {
        expect(run("755")).not.toContain("File type:");
        expect(run("0644")).not.toContain("File type:");
    });

    test("parses a full four digit octal permission string including all special bits", () => {
        const output = run("7777");

        expectSummary(output, "-rwsrwsrwt", "7777");
        expect(flagLines(output)).toEqual([
            "The setuid flag is set",
            "The setgid flag is set",
            "The sticky bit is set"
        ]);
    });

    test("reports the setuid flag for a leading 4", () => {
        const output = run("4755");

        expectSummary(output, "-rwsr-xr-x", "4755");
        expect(flagLines(output)).toEqual(["The setuid flag is set"]);
        expect(output).toContain(" | Execute |   X   |   X   |   X   |");
        expect(output).toContain(" |   Write |   X   |       |       |");
    });

    test("reports the setgid flag for a leading 2", () => {
        const output = run("2755");

        expectSummary(output, "-rwxr-sr-x", "2755");
        expect(flagLines(output)).toEqual(["The setgid flag is set"]);
    });

    test("reports the sticky bit for a leading 1", () => {
        const output = run("1755");

        expectSummary(output, "-rwxr-xr-t", "1755");
        expect(flagLines(output)).toEqual(["The sticky bit is set"]);
    });

    test("renders a leading zero for the special bits when none are set", () => {
        const output = run("644");

        expectSummary(output, "-rw-r--r--", "0644");
        expect(flagLines(output)).toEqual([]);
        expect(output).toContain(" |    Read |   X   |   X   |   X   |");
        expect(output).toContain(" |   Write |   X   |       |       |");
        expect(output).toContain(" | Execute |       |       |       |");
    });

    test("parses a single digit octal string, leaving group and other empty", () => {
        const output = run("7");

        expectSummary(output, "-rwx------", "0700");
        expect(output).toContain(" |    Read |   X   |       |       |");
        expect(output).toContain(" |   Write |   X   |       |       |");
        expect(output).toContain(" | Execute |   X   |       |       |");
    });

    test("parses a two digit octal string, leaving other empty", () => {
        const output = run("64");

        expectSummary(output, "-rw-r-----", "0640");
        expect(output).toContain(" |    Read |   X   |   X   |       |");
        expect(output).toContain(" |   Write |   X   |       |       |");
        expect(output).toContain(" | Execute |       |       |       |");
    });

    test("parses zero as no permissions at all", () => {
        const output = run("0");

        expectSummary(output, "----------", "0000");
        expect(flagLines(output)).toEqual([]);
        expect(output).toBe(
            "Textual representation: ----------\n" +
            "Octal representation:   0000\n" +
            "\n" +
            matrix({
                user:  [false, false, false],
                group: [false, false, false],
                other: [false, false, false]
            })
        );
    });

    test("parses zero padded four digit octal strings", () => {
        expectSummary(run("0000"), "----------", "0000");
        expectSummary(run("0755"), "-rwxr-xr-x", "0755");
        expectSummary(run("0644"), "-rw-r--r--", "0644");
    });

    test("tolerates surrounding whitespace", () => {
        const output = run("  755  ");

        expectSummary(output, "-rwxr-xr-x", "0755");
        expect(output).toBe(run("755"));
    });

    test("ignores the args argument", () => {
        expect(op.run("755", [{ option: true }])).toBe(op.run("755", []));
    });

});


describe("ParseUNIXFilePermissions.run: textual input", () => {

    test("parses a directory permission string", () => {
        const output = run("drwxr-xr-x");

