    });

    test("keeps the sticky bit without execute, rendering an upper case T", () => {
        const output = run("drwxrwxrwT");

        expectSummary(output, "drwxrwxrwT", "1776", "Directory");
        expect(flagLines(output)).toEqual(["The sticky bit is set"]);
        expect(output).toContain(" | Execute |   X   |   X   |       |");
    });

    test("parses a permission string with no permissions granted", () => {
        const output = run("d---------");

