                .toBe(op.run(cleanBytes, ["A-Za-z0-9+/=", false, "Base64"]));
        });
    });

    describe("HTML escaping", () => {
        it("escapes characters decoded into tooltip titles and static text", () => {
            const out = op.run([60, 62, 38], rawArgs(true));

