                "Offset 1: <span class='hl3'>A</span><span class='hl5'>E</span><span data-toggle='tooltip' data-placement='top' title=''>FCQ</span><span class='hl5'>w</span><span class='hl3'>==</span>\n" +
                "Offset 2: <span class='hl3'>AA</span><span class='hl5'>B</span><span data-toggle='tooltip' data-placement='top' title=''>BQk</span><span class='hl5'>M</span><span class='hl3'>=</span>" +
