/**
 * Tests for HTMLIngredient.toHtml().
 *
 * @license Apache-2.0
 */

let HTMLIngredient;

beforeAll(function() {
    return import("../../../src/web/HTMLIngredient.mjs").then(function(mod) {
        HTMLIngredient = mod.default;
    });
});

/**
 * Builds an HTMLIngredient against lightweight stand-ins for the App and Manager.
 *
 * @param {Object} config
 * @returns {{ingredient: HTMLIngredient, manager: Object}}
 */
function buildIngredient(config) {
    let nextId = 0;
    const app = {
        nextIngId: function() {
            nextId += 1;
            return nextId;
        }
    };
    const manager = {
        listeners: [],
        addDynamicListener: function(selector, event, fn, ctx) {
            manager.listeners.push({
                selector: selector,
                event: event,
                fn: fn,
                ctx: ctx
            });
        }
    };
    return {
        ingredient: new HTMLIngredient(config, app, manager),
        manager: manager
    };
}

describe("HTMLIngredient.toHtml", () => {
    describe("text-like ingredient types", () => {
        ["string", "binaryString", "byteArray"].forEach((type) => {
            test(`renders a wide text input for "${type}"`, () => {
                const {ingredient} = buildIngredient({
                    name: "Arg",
                    type: type,
                    value: "hello"
                });

                const html = ingredient.toHtml();

                expect(html).toContain('class="form-group ing-wide"');
                expect(html).toContain('for="ing-1"');
                expect(html).toContain('class="bmd-label-floating">Arg</label>');
                expect(html).toContain('type="text"');
                expect(html).toContain('class="form-control arg"');
                expect(html).toContain('id="ing-1"');
                expect(html).toContain('tabindex="3"');
                expect(html).toContain('arg-name="Arg"');
                expect(html).toContain('value="hello"');
                expect(html).not.toContain("disabled");
                expect(html).not.toContain("maxlength");
                expect(html).not.toContain("data-toggle=\"tooltip\"");
            });
        });

        ["shortString", "binaryShortString"].forEach((type) => {
            test(`renders a short inline text input for "${type}"`, () => {
                const {ingredient} = buildIngredient({
                    name: "ShortArg",
                    type: type,
                    value: "abc"
                });

                const html = ingredient.toHtml();

                expect(html).toContain('class="form-group ing-short"');
                expect(html).toContain('class="bmd-label-floating inline">ShortArg</label>');
                expect(html).toContain('class="form-control arg inline"');
                expect(html).toContain('id="ing-1"');
                expect(html).toContain('tabindex="3"');
                expect(html).toContain('arg-name="ShortArg"');
                expect(html).toContain('value="abc"');
                expect(html).not.toContain("disabled");
            });
        });

        test("does not add any hint attributes when no hint is configured", () => {
            const {ingredient} = buildIngredient({name: "Arg", type: "string", value: ""});

            expect(ingredient.toHtml()).not.toContain("title=");
        });

        test("adds tooltip attributes when a hint is configured", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "",
                hint: "Some helpful text"
            });

            const html = ingredient.toHtml();

            expect(html).toContain('data-toggle="tooltip" title="Some helpful text"');
        });

        test("adds the disabled attribute when the ingredient is disabled", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "val",
                disabled: true
            });

            expect(ingredient.toHtml()).toContain("disabled");
        });

        test("adds a maxlength attribute when maxLength is set", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "val",
                maxLength: 12
            });

            expect(ingredient.toHtml()).toContain('maxlength="12"');
        });

        test("omits maxlength when maxLength is zero", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "val",
                maxLength: 0
            });

            expect(ingredient.toHtml()).not.toContain("maxlength");
        });
    });

    describe("toggleString", () => {
        test("renders a dropdown containing every toggle value", () => {
            const {ingredient} = buildIngredient({
                name: "ToggleArg",
                type: "toggleString",
                value: "ff",
                toggleValues: ["Hex", "Decimal", "Binary"],
                maxLength: 20
            });

            const html = ingredient.toHtml();

            expect(html).toContain('class="form-group input-group ing-wide"');
            expect(html).toContain('data-help-title="Multi-type ingredients"');
            expect(html).toContain('class="toggle-string"');
            expect(html).toContain('class="form-control arg toggle-string"');
            expect(html).toContain('value="ff"');
            expect(html).toContain('maxlength="20"');
            expect(html).toContain('>Hex</button>');
            expect(html).toContain('<a class="dropdown-item" href="#">Hex</a>');
            expect(html).toContain('<a class="dropdown-item" href="#">Decimal</a>');
            expect(html).toContain('<a class="dropdown-item" href="#">Binary</a>');
            expect(html.split('class="dropdown-item"').length - 1).toBe(3);

            const firstIdx = html.indexOf(">Hex</a>");
            const secondIdx = html.indexOf(">Decimal</a>");
            const thirdIdx = html.indexOf(">Binary</a>");
            expect(firstIdx).toBeGreaterThan(-1);
            expect(secondIdx).toBeGreaterThan(firstIdx);
            expect(thirdIdx).toBeGreaterThan(secondIdx);
        });
    });

    describe("number", () => {
        test("renders a number input with min, max and step", () => {
            const {ingredient} = buildIngredient({
                name: "NumArg",
                type: "number",
                value: 5,
                min: 0,
                max: 10,
                step: 0.5
            });

            const html = ingredient.toHtml();

            expect(html).toContain('class="form-group inline ing-medium"');
            expect(html).toContain('type="number"');
            expect(html).toContain('class="form-control arg inline"');
            expect(html).toContain('value="5"');
            expect(html).toContain('min="0"');
            expect(html).toContain('max="10"');
            expect(html).toContain('step="0.5"');
        });

        test("defaults min and max to empty strings and step to 1", () => {
            const {ingredient} = buildIngredient({
                name: "NumArg",
                type: "number",
                value: 3
            });

            const html = ingredient.toHtml();

            expect(html).toContain('min=""');
            expect(html).toContain('max=""');
            expect(html).toContain('step="1"');
        });

        test("ignores non-numeric min and max values", () => {
            const {ingredient} = buildIngredient({
                name: "NumArg",
                type: "number",
                value: 3,
                min: "2",
                max: "9"
            });

            const html = ingredient.toHtml();

            expect(html).toContain('min=""');
            expect(html).toContain('max=""');
        });
    });

    describe("boolean", () => {
        test("renders a checked checkbox when the value is truthy", () => {
            const {ingredient} = buildIngredient({
                name: "BoolArg",
                type: "boolean",
                value: true
            });

            const html = ingredient.toHtml();

            expect(html).toContain('class="form-group inline boolean-arg ing-flexible"');
            expect(html).toContain('type="checkbox"');
            expect(html).toContain(' checked');
            expect(html).toContain(' value="BoolArg"> BoolArg');
            expect(html).not.toContain(" disabled");
        });

        test("renders an unchecked checkbox when the value is false", () => {
            const {ingredient} = buildIngredient({
                name: "BoolArg",
                type: "boolean",
                value: false
            });

            const html = ingredient.toHtml();

            expect(html).not.toContain("checked");
        });

        test("renders a disabled checkbox when disabled", () => {
            const {ingredient} = buildIngredient({
                name: "BoolArg",
                type: "boolean",
                value: true,
                disabled: true
            });

            expect(ingredient.toHtml()).toContain(" disabled");
        });
    });

    describe("option", () => {
        test("renders plain options and marks the default one as selected", () => {
            const {ingredient} = buildIngredient({
                name: "OptArg",
                type: "option",
                value: ["A", "B", "C"],
                defaultIndex: 1
            });

            const html = ingredient.toHtml();

            expect(html).toContain('class="form-group ing-medium"');
            expect(html).toContain('<select');
            expect(html).toContain('<option >A</option>');
            expect(html).toContain('<option selected>B</option>');
            expect(html).toContain('<option >C</option>');
            expect(html.split("<option").length - 1).toBe(3);
            expect(html).not.toContain("optgroup");
        });

        test("defaults to selecting the first option", () => {
            const {ingredient} = buildIngredient({
                name: "OptArg",
                type: "option",
                value: ["A", "B"]
            });

            const html = ingredient.toHtml();

            expect(html).toContain('<option selected>A</option>');
            expect(html).toContain('<option >B</option>');
        });

        test("translates group markers into optgroups", () => {
            const {ingredient} = buildIngredient({
                name: "OptArg",
                type: "option",
                value: ["[Group One]", "A", "[/Group One]", "B"],
                defaultIndex: 1
            });

            const html = ingredient.toHtml();

            expect(html).toContain('<optgroup label="Group One">');
            expect(html).toContain("</optgroup>");
            expect(html).toContain('<option selected>A</option>');

            const openIdx = html.indexOf('<optgroup label="Group One">');
            const optIdx = html.indexOf('<option selected>A</option>');
            const closeIdx = html.indexOf("</optgroup>");
            const outsideIdx = html.indexOf("<option >B</option>");
            expect(openIdx).toBeGreaterThan(-1);
            expect(optIdx).toBeGreaterThan(openIdx);
            expect(closeIdx).toBeGreaterThan(optIdx);
            expect(outsideIdx).toBeGreaterThan(closeIdx);
            // Group markers must not be rendered as options
            expect(html).not.toContain(">A[/Group One]<");
            expect(html.split("<option").length - 1).toBe(2);
