/* global beforeAll, describe, test, expect */

/**
 * Tests for HTMLIngredient.toHtml().
 *
 * @license Apache-2.0
 */

let HTMLIngredient;

beforeAll(function() {
    return import("../../../src/web/HTMLIngredient.mjs").then(function(mod) {
        HTMLIngredient = mod.default;
    });
});

/**
 * Builds an HTMLIngredient against lightweight stand-ins for the App and Manager.
 *
 * @param {Object} config
 * @returns {{ingredient: HTMLIngredient, manager: Object}}
 */
function buildIngredient(config) {
    let nextId = 0;
    const app = {
        nextIngId: function() {
            nextId += 1;
            return nextId;
        }
    };
    const manager = {
        listeners: [],
        addDynamicListener: function(selector, event, fn, ctx) {
            manager.listeners[manager.listeners.length] = {
                selector: selector,
                event: event,
                fn: fn,
                ctx: ctx
            };
        }
    };
    return {
        ingredient: new HTMLIngredient(config, app, manager),
        manager: manager
    };
}

describe("HTMLIngredient.toHtml", () => {
    describe("text-like ingredient types", () => {
        ["string", "binaryString", "byteArray"].forEach((type) => {
            test(`renders a wide text input for "${type}"`, () => {
                const {ingredient} = buildIngredient({
                    name: "Arg",
                    type: type,
                    value: "hello"
                });

                const html = ingredient.toHtml();

                expect(html).toContain("class=\"form-group ing-wide\"");
                expect(html).toContain("for=\"ing-1\"");
                expect(html).toContain("class=\"bmd-label-floating\">Arg</label>");
                expect(html).toContain("type=\"text\"");
                expect(html).toContain("class=\"form-control arg\"");
                expect(html).toContain("id=\"ing-1\"");
                expect(html).toContain("tabindex=\"3\"");
                expect(html).toContain("arg-name=\"Arg\"");
                expect(html).toContain("value=\"hello\"");
                expect(html).not.toContain("disabled");
                expect(html).not.toContain("maxlength");
                expect(html).not.toContain("data-toggle=\"tooltip\"");
            });
        });

        ["shortString", "binaryShortString"].forEach((type) => {
            test(`renders a short inline text input for "${type}"`, () => {
                const {ingredient} = buildIngredient({
                    name: "ShortArg",
                    type: type,
                    value: "abc"
                });

                const html = ingredient.toHtml();

                expect(html).toContain("class=\"form-group ing-short\"");
                expect(html).toContain("class=\"bmd-label-floating inline\">ShortArg</label>");
                expect(html).toContain("class=\"form-control arg inline\"");
                expect(html).toContain("id=\"ing-1\"");
                expect(html).toContain("tabindex=\"3\"");
                expect(html).toContain("arg-name=\"ShortArg\"");
                expect(html).toContain("value=\"abc\"");
                expect(html).not.toContain("disabled");
            });
        });

        test("does not add any hint attributes when no hint is configured", () => {
            const {ingredient} = buildIngredient({name: "Arg", type: "string", value: ""});

            expect(ingredient.toHtml()).not.toContain("title=");
        });

        test("adds tooltip attributes when a hint is configured", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "",
                hint: "Some helpful text"
            });

            const html = ingredient.toHtml();

            expect(html).toContain("data-toggle=\"tooltip\" title=\"Some helpful text\"");
        });

        test("adds the disabled attribute when the ingredient is disabled", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "val",
                disabled: true
            });

            expect(ingredient.toHtml()).toContain("disabled");
        });

        test("adds a maxlength attribute when maxLength is set", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "val",
                maxLength: 12
            });

            expect(ingredient.toHtml()).toContain("maxlength=\"12\"");
        });

        test("omits maxlength when maxLength is zero", () => {
            const {ingredient} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "val",
                maxLength: 0
            });

            expect(ingredient.toHtml()).not.toContain("maxlength");
        });
    });

    describe("toggleString", () => {
        test("renders a dropdown containing every toggle value", () => {
            const {ingredient} = buildIngredient({
                name: "ToggleArg",
                type: "toggleString",
                value: "ff",
                toggleValues: ["Hex", "Decimal", "Binary"],
                maxLength: 20
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group input-group ing-wide\"");
            expect(html).toContain("data-help-title=\"Multi-type ingredients\"");
            expect(html).toContain("class=\"toggle-string\"");
            expect(html).toContain("class=\"form-control arg toggle-string\"");
            expect(html).toContain("value=\"ff\"");
            expect(html).toContain("maxlength=\"20\"");
            expect(html).toContain(">Hex</button>");
            expect(html).toContain("<a class=\"dropdown-item\" href=\"#\">Hex</a>");
            expect(html).toContain("<a class=\"dropdown-item\" href=\"#\">Decimal</a>");
            expect(html).toContain("<a class=\"dropdown-item\" href=\"#\">Binary</a>");
            expect(html.split("class=\"dropdown-item\"").length - 1).toBe(3);
            expect(html).toMatch(/>Hex<\/a>[^]*>Decimal<\/a>[^]*>Binary<\/a>/);
        });
    });

    describe("number", () => {
        test("renders a number input with min, max and step", () => {
            const {ingredient} = buildIngredient({
                name: "NumArg",
                type: "number",
                value: 5,
                min: 0,
                max: 10,
                step: 0.5
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group inline ing-medium\"");
            expect(html).toContain("type=\"number\"");
            expect(html).toContain("class=\"form-control arg inline\"");
            expect(html).toContain("value=\"5\"");
            expect(html).toContain("min=\"0\"");
            expect(html).toContain("max=\"10\"");
            expect(html).toContain("step=\"0.5\"");
        });

        test("defaults min and max to empty strings and step to 1", () => {
            const {ingredient} = buildIngredient({
                name: "NumArg",
                type: "number",
                value: 3
            });

            const html = ingredient.toHtml();

            expect(html).toContain("min=\"\"");
            expect(html).toContain("max=\"\"");
            expect(html).toContain("step=\"1\"");
        });

        test("ignores non-numeric min and max values", () => {
            const {ingredient} = buildIngredient({
                name: "NumArg",
                type: "number",
                value: 3,
                min: "2",
                max: "9"
            });

            const html = ingredient.toHtml();

            expect(html).toContain("min=\"\"");
            expect(html).toContain("max=\"\"");
        });
    });

    describe("boolean", () => {
        test("renders a checked checkbox when the value is truthy", () => {
            const {ingredient} = buildIngredient({
                name: "BoolArg",
                type: "boolean",
                value: true
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group inline boolean-arg ing-flexible\"");
            expect(html).toContain("type=\"checkbox\"");
            expect(html).toContain(" checked");
            expect(html).toContain(" value=\"BoolArg\"> BoolArg");
            expect(html).not.toContain(" disabled");
        });

        test("renders an unchecked checkbox when the value is false", () => {
            const {ingredient} = buildIngredient({
                name: "BoolArg",
                type: "boolean",
                value: false
            });

            expect(ingredient.toHtml()).not.toContain("checked");
        });

        test("renders a disabled checkbox when disabled", () => {
            const {ingredient} = buildIngredient({
                name: "BoolArg",
                type: "boolean",
                value: true,
                disabled: true
            });

            expect(ingredient.toHtml()).toContain(" disabled");
        });
    });

    describe("option", () => {
        test("renders plain options and marks the default one as selected", () => {
            const {ingredient} = buildIngredient({
                name: "OptArg",
                type: "option",
                value: ["A", "B", "C"],
                defaultIndex: 1
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group ing-medium\"");
            expect(html).toContain("<select");
            expect(html).toContain("<option >A</option>");
            expect(html).toContain("<option selected>B</option>");
            expect(html).toContain("<option >C</option>");
            expect(html.split("<option").length - 1).toBe(3);
            expect(html).not.toContain("optgroup");
        });

        test("defaults to selecting the first option", () => {
            const {ingredient} = buildIngredient({
                name: "OptArg",
                type: "option",
                value: ["A", "B"]
            });

            const html = ingredient.toHtml();

            expect(html).toContain("<option selected>A</option>");
            expect(html).toContain("<option >B</option>");
        });

        test("translates group markers into optgroups", () => {
            const {ingredient} = buildIngredient({
                name: "OptArg",
                type: "option",
                value: ["[Group One]", "A", "[/Group One]", "B"],
                defaultIndex: 1
            });

            const html = ingredient.toHtml();

            expect(html).toContain("<optgroup label=\"Group One\">");
            expect(html).toContain("</optgroup>");
            expect(html).toContain("<option selected>A</option>");
            expect(html).toMatch(/<optgroup label="Group One">[^]*<option selected>A<\/option>[^]*<\/optgroup>[^]*<option >B<\/option>/);
            expect(html).not.toContain("[/Group One]</option>");
            expect(html.split("<option").length - 1).toBe(2);
        });

        test("renders a disabled select when disabled", () => {
            const {ingredient} = buildIngredient({
                name: "OptArg",
                type: "option",
                value: ["A"],
                disabled: true
            });

            expect(ingredient.toHtml()).toContain("disabled");
        });
    });

    describe("populateOption", () => {
        test("renders options with escaped populate values and registers a change listener", () => {
            const {ingredient, manager} = buildIngredient({
                name: "PopArg",
                type: "populateOption",
                value: [
                    {name: "Preset", value: "<b>&\"x\"</b>"},
                    {name: "[Group]", value: ""},
                    {name: "Other", value: "plain"},
                    {name: "[/Group]", value: ""}
                ],
                target: 2
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group ing-medium\"");
            expect(html).toContain("data-help-title=\"Population dropdowns\"");
            expect(html).toContain("class=\"form-control arg no-state-change populate-option\"");
            expect(html).toContain("data-target=\"2\"");
            expect(html).toContain("<option populate-value='&lt;b&gt;&amp;&quot;x&quot;&lt;/b&gt;'>Preset</option>");
            expect(html).toContain("<option populate-value='plain'>Other</option>");
            expect(html).toContain("<optgroup label=\"Group\">");
            expect(html).toContain("</optgroup>");
            expect(html.split("<option").length - 1).toBe(2);

            expect(manager.listeners.length).toBe(1);
            expect(manager.listeners[0].selector).toBe("#ing-1");
            expect(manager.listeners[0].event).toBe("change");
            expect(manager.listeners[0].fn).toBe(ingredient.populateOptionChange);
            expect(manager.listeners[0].ctx).toBe(ingredient);
        });
    });

    describe("populateMultiOption", () => {
        test("JSON-encodes and escapes populate values and uses the multi change handler", () => {
            const {ingredient, manager} = buildIngredient({
                name: "PopMulti",
                type: "populateMultiOption",
                value: [
                    {name: "Preset One", value: ["<x>", "y&z"]}
                ],
                target: [0, 1]
            });

            const html = ingredient.toHtml();

            expect(html).toContain("data-target=\"0,1\"");
            expect(html).toContain("<option populate-value='[&quot;&lt;x&gt;&quot;,&quot;y&amp;z&quot;]'>Preset One</option>");

            expect(manager.listeners.length).toBe(1);
            expect(manager.listeners[0].selector).toBe("#ing-1");
            expect(manager.listeners[0].event).toBe("change");
            expect(manager.listeners[0].fn).toBe(ingredient.populateMultiOptionChange);
            expect(manager.listeners[0].ctx).toBe(ingredient);
        });

        test("supports optgroups in the population list", () => {
            const {ingredient} = buildIngredient({
                name: "PopMulti",
                type: "populateMultiOption",
                value: [
                    {name: "[Group]", value: []},
                    {name: "Preset", value: [1, 2]}
                ],
                target: [0]
            });

            const html = ingredient.toHtml();

            expect(html).toContain("<optgroup label=\"Group\">");
            expect(html).toContain("<option populate-value='[1,2]'>Preset</option>");
            expect(html.split("<option").length - 1).toBe(1);
        });
    });

    describe("editableOption", () => {
        test("renders the value at defaultIndex in the input and all options in the menu", () => {
            const {ingredient, manager} = buildIngredient({
                name: "EditArg",
                type: "editableOption",
                value: [
                    {name: "One", value: "1"},
                    {name: "Two", value: "2"}
                ],
                defaultIndex: 1
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group input-group ing-wide\"");
            expect(html).toContain("class=\"form-control arg\"");
            expect(html).toContain("value=\"2\"");
            expect(html).toContain("class=\"dropdown-menu editable-option-menu\"");
            expect(html).toContain("<a class=\"dropdown-item\" href=\"#\" value=\"1\">One</a>");
            expect(html).toContain("<a class=\"dropdown-item\" href=\"#\" value=\"2\">Two</a>");

            expect(manager.listeners.length).toBe(1);
            expect(manager.listeners[0].selector).toBe(".editable-option-menu a");
            expect(manager.listeners[0].event).toBe("click");
            expect(manager.listeners[0].fn).toBe(ingredient.editableOptionClick);
            expect(manager.listeners[0].ctx).toBe(ingredient);
        });

        test("uses the first option when defaultIndex is not supplied", () => {
            const {ingredient} = buildIngredient({
                name: "EditArg",
                type: "editableOption",
                value: [
                    {name: "One", value: "first"},
                    {name: "Two", value: "second"}
                ]
            });

            expect(ingredient.toHtml()).toContain("value=\"first\"");
        });
    });

    describe("editableOptionShort", () => {
        test("renders a short inline editable option input", () => {
            const {ingredient, manager} = buildIngredient({
                name: "EditShort",
                type: "editableOptionShort",
                value: [
                    {name: "One", value: "alpha"},
                    {name: "Two", value: "beta"}
                ]
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group input-group ing-short\"");
            expect(html).toContain("class=\"form-control arg inline\"");
            expect(html).toContain("class=\"input-group-append inline\"");
            expect(html).toContain("value=\"alpha\"");
            expect(html).toContain("<a class=\"dropdown-item\" href=\"#\" value=\"beta\">Two</a>");

            expect(manager.listeners.length).toBe(1);
            expect(manager.listeners[0].selector).toBe(".editable-option-menu a");
            expect(manager.listeners[0].event).toBe("click");
            expect(manager.listeners[0].fn).toBe(ingredient.editableOptionClick);
        });
    });

    describe("text", () => {
        test("renders a textarea with the default of three rows", () => {
            const {ingredient} = buildIngredient({
                name: "TextArg",
                type: "text",
                value: "line one\nline two"
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group ing-very-wide\"");
            expect(html).toContain("<textarea");
            expect(html).toContain("class=\"form-control arg\"");
            expect(html).toContain("rows=\"3\"");
            expect(html).toContain(">line one\nline two</textarea>");
        });

        test("uses the configured number of rows", () => {
            const {ingredient} = buildIngredient({
                name: "TextArg",
                type: "text",
                value: "",
                rows: 8,
                disabled: true
            });

            const html = ingredient.toHtml();

            expect(html).toContain("rows=\"8\"");
            expect(html).toContain("disabled");
        });
    });

    describe("argSelector", () => {
        test("renders options with turnon/turnoff metadata and marks the default as selected", () => {
            const {ingredient, manager} = buildIngredient({
                name: "Selector",
                type: "argSelector",
                value: [
                    {name: "First", on: [0], off: [1]},
                    {name: "Second"}
                ],
                defaultIndex: 1
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-control arg inline arg-selector\"");
            expect(html).toContain("data-help-title=\"Ingredient selector\"");
            expect(html).toContain("turnon=\"[0]\"");
            expect(html).toContain("turnoff=\"[1]\"");
            expect(html).toContain("turnon=\"[]\"");
            expect(html).toContain("turnoff=\"[]\"");
            expect(html).toContain("<option selected");
            expect(html).toContain("First");
            expect(html).toContain("Second");

            expect(manager.listeners.length).toBe(1);
            expect(manager.listeners[0].selector).toBe(".arg-selector");
            expect(manager.listeners[0].event).toBe("change");
            expect(manager.listeners[0].fn).toBe(ingredient.argSelectorChange);
            expect(manager.listeners[0].ctx).toBe(ingredient);
        });

        test("does not select any option when defaultIndex is out of range", () => {
            const {ingredient} = buildIngredient({
                name: "Selector",
                type: "argSelector",
                value: [{name: "Only"}],
                defaultIndex: 5
            });

            expect(ingredient.toHtml()).not.toContain("selected");
        });
    });

    describe("label", () => {
        test("renders a hidden input without a tabindex", () => {
            const {ingredient} = buildIngredient({
                name: "LabelArg",
                type: "label",
                value: ""
            });

            const html = ingredient.toHtml();

            expect(html).toContain("class=\"form-group ing-flexible\"");
            expect(html).toContain("<label>LabelArg</label>");
            expect(html).toContain("type=\"hidden\"");
            expect(html).toContain("id=\"ing-1\"");
            expect(html).toContain("arg-name=\"LabelArg\"");
            expect(html).not.toContain("tabindex");
        });
    });

    describe("generic behaviour", () => {
        test("returns an empty string for unknown ingredient types", () => {
            const {ingredient} = buildIngredient({
                name: "Mystery",
                type: "unknownType",
                value: "x"
            });

            expect(ingredient.toHtml()).toBe("");
        });

        test("returns an empty string when no type is supplied", () => {
            const {ingredient} = buildIngredient({name: "Mystery", value: "x"});

            expect(ingredient.toHtml()).toBe("");
        });

        test("assigns sequential ids and tab indexes", () => {
            let nextId = 0;
            const app = {
                nextIngId: function() {
                    nextId += 1;
                    return nextId;
                }
            };
            const manager = {addDynamicListener: function() {}};

            const first = new HTMLIngredient({name: "One", type: "string", value: ""}, app, manager);
            const second = new HTMLIngredient({name: "Two", type: "string", value: ""}, app, manager);

            expect(first.toHtml()).toContain("id=\"ing-1\"");
            expect(first.toHtml()).toContain("tabindex=\"3\"");
            expect(second.toHtml()).toContain("id=\"ing-2\"");
            expect(second.toHtml()).toContain("tabindex=\"4\"");
        });

        test("does not register listeners for types that require none", () => {
            const {ingredient, manager} = buildIngredient({
                name: "Arg",
                type: "string",
                value: "v"
            });

            ingredient.toHtml();

            expect(manager.listeners.length).toBe(0);
        });
    });
});
