const path = require("path");
const { JSDOM } = require("jsdom");

const sourcePath = path.resolve(
    __dirname,
    "../../../../src/web/waiters/BindingsWaiter.mjs"
);

/**
 * Load the production .mjs class in Jest's CommonJS test environment.
 * It contains only one ES module statement, so convert that export locally
