function loadBindingsWaiter() {
    const source = fs.readFileSync(sourcePath, "utf8");
    const commonJsSource = source.replace(
        /export\s+default\s+BindingsWaiter\s*;?\s*$/,
        "module.exports = BindingsWaiter;"
    );

    if (commonJsSource === source) {
        throw new Error("Could not convert BindingsWaiter's default export for testing");
    }

    const sourceModule = { exports: {} };
    const load = new Function("module", "exports", commonJsSource);
    load(sourceModule, sourceModule.exports);

    return sourceModule.exports;
}

const BindingsWaiter = loadBindingsWaiter();

function makeEvent(code, overrides = {}) {
    const event = {
        code,
        ctrlKey: true,
        altKey: true,
        metaKey: false,
        preventDefault: jest.fn()
    };

    for (const key of Object.keys(overrides)) {
        event[key] = overrides[key];
    }

    return event;
}

function makeManager(dom) {
    return {
        input: {
            inputEditorView: { focus: jest.fn() },
            addInputClick: jest.fn(),
            removeInput: jest.fn(),
            changeTabLeft: jest.fn(),
            changeTabRight: jest.fn()
        },
        output: {
            outputEditorView: { focus: jest.fn() },
            saveClick: jest.fn(),
            switchClick: jest.fn()
        },
        controls: {
            bakeClick: jest.fn(),
            stepClick: jest.fn(),
            loadClick: jest.fn()
        },
        recipe: {
