        },
        tabs: {
            getActiveTab: jest.fn().mockReturnValue("active-input-tab")
        },
        statechange: new dom.window.Event("statechange")
    };
}

describe("BindingsWaiter.parseInput", () => {
    let dom;
    let app;
    let manager;
    let waiter;
    let dispatchSpy;

    beforeEach(() => {
        dom = new JSDOM("<!doctype html><html><body></body></html>", {
            url: "http://localhost/"
        });

        global.window = dom.window;
        global.document = dom.window.document;
        global.navigator = dom.window.navigator;

        app = {
            options: { useMetaKey: false },
            progress: 100
        };
        manager = makeManager(dom);
        waiter = new BindingsWaiter(app, manager);
        waiter.contextualHelp = jest.fn();
        dispatchSpy = jest.spyOn(global.window, "dispatchEvent");
    });

    afterEach(() => {
        jest.restoreAllMocks();
        dom.window.close();
        delete global.window;
        delete global.document;
        delete global.navigator;
    });

    describe("modifier-key gating", () => {
        it("does nothing when Ctrl is not held", () => {
            const event = makeEvent("Space", { ctrlKey: false, altKey: true });

            waiter.parseInput(event);

            expect(event.preventDefault).not.toHaveBeenCalled();
            expect(manager.controls.bakeClick).not.toHaveBeenCalled();
        });

        it("uses Alt as the platform modifier when useMetaKey is false", () => {
            const event = makeEvent("Space", { ctrlKey: true, altKey: true, metaKey: false });

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(manager.controls.bakeClick).toHaveBeenCalledTimes(1);
        });

        it("does not accept the Meta modifier when useMetaKey is false", () => {
            const event = makeEvent("Space", { ctrlKey: true, altKey: false, metaKey: true });

            waiter.parseInput(event);

            expect(event.preventDefault).not.toHaveBeenCalled();
            expect(manager.controls.bakeClick).not.toHaveBeenCalled();
        });

        it("uses Meta as the platform modifier when useMetaKey is true", () => {
            app.options.useMetaKey = true;
            const event = makeEvent("Space", { ctrlKey: true, altKey: false, metaKey: true });

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(manager.controls.bakeClick).toHaveBeenCalledTimes(1);
        });

        it("does not accept the Alt modifier when useMetaKey is true", () => {
            app.options.useMetaKey = true;
            const event = makeEvent("Space", { ctrlKey: true, altKey: true, metaKey: false });

            waiter.parseInput(event);

            expect(event.preventDefault).not.toHaveBeenCalled();
            expect(manager.controls.bakeClick).not.toHaveBeenCalled();
        });
    });

    describe("editor focus shortcuts", () => {
        it("focuses the search field on KeyF", () => {
            document.body.innerHTML = '<input id="search">';
            const search = document.getElementById("search");
            const focusSpy = jest.spyOn(search, "focus");
            const event = makeEvent("KeyF");

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(focusSpy).toHaveBeenCalledTimes(1);
            expect(document.activeElement).toBe(search);
        });

        it("focuses the input editor on KeyI", () => {
            const event = makeEvent("KeyI");

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(manager.input.inputEditorView.focus).toHaveBeenCalledTimes(1);
        });

        it("focuses the output editor on KeyO", () => {
            const event = makeEvent("KeyO");

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(manager.output.outputEditorView.focus).toHaveBeenCalledTimes(1);
        });
    });

    describe("operation navigation and toggles", () => {
        it("focuses the first argument of the next operation on Period", () => {
            document.body.innerHTML = '<div id="rec-list">' +
                '<div class="operation" id="op1"><input class="arg" id="arg1"></div>' +
                '<div class="operation" id="op2"><input class="arg" id="arg2"><input class="arg"></div>' +
                "</div>";
            document.getElementById("arg1").focus();
            const nextArg = document.getElementById("arg2");
            jest.spyOn(nextArg, "focus");
            const event = makeEvent("Period");

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(nextArg.focus).toHaveBeenCalledTimes(1);
            expect(document.activeElement).toBe(nextArg);
        });

        it("wraps to the first operation's first argument when Period is used on the last operation", () => {
            document.body.innerHTML = '<div id="rec-list">' +
                '<div class="operation" id="op1"><input class="arg" id="arg1"></div>' +
                '<div class="operation" id="op2"><input class="arg" id="arg2"></div>' +
                "</div>";
            document.getElementById("arg2").focus();
            const firstArg = document.getElementById("arg1");
            jest.spyOn(firstArg, "focus");
            const event = makeEvent("Period");

            waiter.parseInput(event);

            expect(firstArg.focus).toHaveBeenCalledTimes(1);
            expect(document.activeElement).toBe(firstArg);
        });

        it("falls back to the first recipe operation when focus is outside an operation", () => {
            document.body.innerHTML = '<div id="rec-list">' +
                '<div class="operation" id="only-op"><input class="arg" id="only-arg"></div>' +
                "</div>";
            const onlyArg = document.getElementById("only-arg");
            jest.spyOn(onlyArg, "focus");
            const event = makeEvent("Period");

            waiter.parseInput(event);

            expect(onlyArg.focus).toHaveBeenCalledTimes(1);
            expect(document.activeElement).toBe(onlyArg);
        });

        it("silently ignores Period when no operation can be found", () => {
            const event = makeEvent("Period");

            expect(() => waiter.parseInput(event)).not.toThrow();
            expect(event.preventDefault).toHaveBeenCalledTimes(1);
        });

        it("toggles a breakpoint and dispatches a statechange event on KeyB", () => {
            document.body.innerHTML = `
                <div class="operation">
                    <input id="active">
                    <span class="breakpoint" break="false"></span>
                </div>`;
            document.getElementById("active").focus();
            const breakpoint = document.querySelector(".breakpoint");
            const event = makeEvent("KeyB");

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(breakpoint.getAttribute("break")).toBe("true");
            expect(breakpoint.classList.contains("breakpoint-selected")).toBe(true);
            expect(dispatchSpy).toHaveBeenCalledWith(manager.statechange);

            waiter.parseInput(makeEvent("KeyB"));

            expect(breakpoint.getAttribute("break")).toBe("false");
            expect(breakpoint.classList.contains("breakpoint-selected")).toBe(false);
            expect(dispatchSpy).toHaveBeenCalledTimes(2);
        });

        it("silently ignores KeyB when the active element is not in an operation", () => {
            const event = makeEvent("KeyB");

            expect(() => waiter.parseInput(event)).not.toThrow();
            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(dispatchSpy).not.toHaveBeenCalled();
        });

        it("toggles an operation's disabled state and dispatches a statechange event on KeyD", () => {
            document.body.innerHTML = `
                <div class="operation" id="operation">
                    <input id="active">
                    <div class="icon-wrapper"><span class="disable-icon" disabled="false"></span></div>
                </div>`;
            document.getElementById("active").focus();
            const operation = document.getElementById("operation");
            const disableIcon = document.querySelector(".disable-icon");
            const event = makeEvent("KeyD");

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(disableIcon.getAttribute("disabled")).toBe("true");
            expect(disableIcon.classList.contains("disable-elem-selected")).toBe(true);
            expect(operation.classList.contains("disabled")).toBe(true);
            expect(app.progress).toBe(0);
            expect(dispatchSpy).toHaveBeenCalledWith(manager.statechange);

            waiter.parseInput(makeEvent("KeyD"));

            expect(disableIcon.getAttribute("disabled")).toBe("false");
            expect(disableIcon.classList.contains("disable-elem-selected")).toBe(false);
            expect(operation.classList.contains("disabled")).toBe(false);
            expect(app.progress).toBe(0);
            expect(dispatchSpy).toHaveBeenCalledTimes(2);
        });

        it("silently ignores KeyD when the active element is not in an operation", () => {
            app.progress = 37;
            const event = makeEvent("KeyD");

            expect(() => waiter.parseInput(event)).not.toThrow();
            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(app.progress).toBe(37);
            expect(dispatchSpy).not.toHaveBeenCalled();
        });
    });

    describe("global command shortcuts", () => {
        it.each([
            ["Space", (m) => m.controls.bakeClick],
            ["Quote", (m) => m.controls.stepClick],
            ["KeyC", (m) => m.recipe.clearRecipe],
            ["KeyS", (m) => m.output.saveClick],
            ["KeyL", (m) => m.controls.loadClick],
            ["KeyM", (m) => m.output.switchClick],
            ["KeyT", (m) => m.input.addInputClick],
            ["ArrowLeft", (m) => m.input.changeTabLeft],
            ["ArrowRight", (m) => m.input.changeTabRight]
        ])("handles %s", (code, getAction) => {
            const event = makeEvent(code);
            const action = getAction(manager);

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(action).toHaveBeenCalledTimes(1);
        });

        it("closes the active input tab on KeyW", () => {
            manager.tabs.getActiveTab.mockReturnValue("tab-to-close");
            const event = makeEvent("KeyW");

            waiter.parseInput(event);

            expect(event.preventDefault).toHaveBeenCalledTimes(1);
            expect(manager.tabs.getActiveTab).toHaveBeenCalledWith("input");
            expect(manager.input.removeInput).toHaveBeenCalledWith("tab-to-close");
        });
    });

